stage_a_raw:
{
  "decisions": [
    {
      "decision": "balance_constraint_sign_convention",
      "evidence": "\"City 0 has a net demand of 2 units (it requires 2 more units than it currently has).\" / \"City 2 has a net supply of 1 unit\"",
      "options": [
        "inflow - outflow == net_demand (demand positive)",
        "outflow - inflow == net_demand (demand positive)"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "inflow - outflow == net_demand (demand positive)"
    },
    {
      "decision": "demand_satisfaction_form",
      "evidence": "\"a demand that must be met\" / \"ensuring that all demands are satisfied\"",
      "options": [
        "equality balance inflow - outflow == net_demand at every city",
        "inequality inflow - outflow >= net_demand at demand cities (demand is a minimum requirement)"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "equality balance inflow - outflow == net_demand at every city"
    },
    {
      "decision": "city_capacity_scope",
      "evidence": "\"Each city has a maximum capacity for incoming resources\"",
      "options": [
        "total inflow <= city_cap",
        "total inflow + outflow <= city_cap",
        "total inflow <= city_cap and total outflow <= city_cap"
      ],
      "plausibility": [
        0.7,
        0.15,
        0.15
      ],
      "majority_option": "total inflow <= city_cap"
    },
    {
      "decision": "flow_variable_domain",
      "evidence": "\"All transportation amounts are non-negative.\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "arc_capacity_encoding",
      "evidence": "\"Each route between cities has a maximum capacity for resource transportation\"",
      "options": [
        "variable bounds 0 <= x[i,j] <= arc_cap[i,j]",
        "explicit constraint x[i,j] <= arc_cap[i,j] with unbounded variable"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "variable bounds 0 <= x[i,j] <= arc_cap[i,j]"
    },
    {
      "decision": "objective_quantity",
      "evidence": "\"minimize the total cost of transporting the resource between cities\"",
      "options": [
        "minimize sum of cost[i,j] * x[i,j] over all directed arcs",
        "minimize sum of cost[i,j] * x[i,j] plus a penalty on unmet demand"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "minimize sum of cost[i,j] * x[i,j] over all directed arcs"
    }
  ]
}
